import datetime

# Billing rows arrive as ISO-8601 dates (YYYY-MM-DD). The parser previously
# expected '%d-%m-%Y', which raised ValueError on every row and failed the
# export. Parse ISO dates, and still accept legacy dd-mm-yyyy rows.
DATE_FORMATS = ('%Y-%m-%d', '%d-%m-%Y')

rows = ['2026-11-08,100.00', '2026-11-07,250.00']


def parse_date(value):
    for fmt in DATE_FORMATS:
        try:
            return datetime.datetime.strptime(value, fmt)
        except ValueError:
            continue
    raise ValueError(f"unrecognised billing date: {value!r}")


for r in rows:
    d, amt = r.split(',')
    print(parse_date(d).date(), amt)

